-- GIV-3D focused acceptance correction: filter/search the same exact amount shown in the issue queue.
-- Authorization, org scope, bounded selection and immutable financial data remain unchanged.
create or replace function private.payment_ops_rows(o uuid,p jsonb)returns jsonb language sql stable security definer set search_path=''as $$
 select coalesce(jsonb_agg(row_data order by created_at desc,id),'[]')from(
 select i.id,i.created_at,jsonb_build_object('id',i.id,'issue_type',i.issue_type,'status',i.status,'priority',i.priority,'assigned_to',i.assigned_to,'revision',i.revision,'date',i.created_at,'next_action',i.next_action,'last_action',i.last_action,'session_id',coalesce(i.session_id,l.session_id),'leg_id',i.leg_id,'instruction_id',i.instruction_id,'method_id',i.method_id,'gateway_id',i.gateway_id,'donor',concat_ws(' ',person.first_name,person.last_name),'person_id',person.id,'amount_minor',display.amount_minor::text,'currency',coalesce(l.currency,rec.currency,s.currency),'provider',g.provider,'gateway',g.label,'merchant_destination',l.route_snapshot->>'destination_label','mid_route',l.route_snapshot->>'route_label','transaction_reference',l.provider_reference)row_data
 from private.payment_ops_issues i left join public.giving_transaction_legs l on(l.organization_id,l.id)=(i.organization_id,i.leg_id)left join public.giving_sessions s on(s.organization_id,s.id)=(i.organization_id,coalesce(i.session_id,l.session_id))left join public.giving_recurring_instructions rec on(rec.organization_id,rec.id)=(i.organization_id,i.instruction_id)left join private.payments_methods met on(met.organization_id,met.id)=(i.organization_id,i.method_id)left join public.giving_refunds adj on adj.organization_id=i.organization_id and i.fingerprint='adjustment:'||adj.id left join public.organization_people person on(person.organization_id,person.id)=(i.organization_id,coalesce(s.person_id,rec.person_id,met.person_id))left join public.giving_gateway_accounts g on(g.organization_id,g.id)=(i.organization_id,coalesce(i.gateway_id,(l.route_snapshot->>'gateway_id')::uuid))
 cross join lateral(select coalesce(adj.amount_minor,l.amount_minor,(select sum(amount_minor)from public.giving_recurring_lines where organization_id=o and instruction_id=i.instruction_id),s.intended_minor) as amount_minor) display
 where i.organization_id=o and(p->>'id'is null or i.id=(p->>'id')::uuid)and(p->>'issue_type'is null or i.issue_type=p->>'issue_type')and(p->>'status'is null or i.status=p->>'status')and(p->>'provider'is null or g.provider=p->>'provider')and(p->>'destination'is null or l.route_snapshot->>'destination_label'=p->>'destination')and(p->>'mid'is null or l.route_snapshot->>'route_label'=p->>'mid')and(p->>'assigned_to'is null or i.assigned_to=(p->>'assigned_to')::uuid)and(p->>'starts_at'is null or i.created_at>=(p->>'starts_at')::timestamptz)and(p->>'ends_at'is null or i.created_at<(p->>'ends_at')::timestamptz)and(p->>'min_minor'is null or display.amount_minor>=(p->>'min_minor')::bigint)and(p->>'max_minor'is null or display.amount_minor<=(p->>'max_minor')::bigint)
 and(p->>'search'is null or concat_ws(' ',person.first_name,person.last_name,person.email,s.id::text,l.provider_reference,display.amount_minor::text,(select string_agg(receipt_number,' ')from public.giving_receipts where organization_id=o and session_id=s.id),(select string_agg(last4,' ')from private.payments_methods where organization_id=o and person_id=s.person_id)) ilike ('%'||(p->>'search')||'%'))order by i.created_at desc,i.id limit 500)x$$;
